xss-escape.query:
; The fix: escape "<" instead of deleting tags.
;
;   function sanitize(comment) {
;     return comment.replaceAll("<", "&lt;");
;   }
;
; Can the output contain any tag opening at all?  (unsat = no)
(set-logic QF_SLIA)
(declare-const comment String)
(define-fun out () String (str.replace_all comment "<" "&lt;"))
(assert (str.contains out "<"))
(check-sat)

xss-strip.query:
; XSS: a "sanitizer" that deletes <script> tags from a comment before it is
; put into an HTML page.
;
;   function sanitize(comment) {
;     return comment.replaceAll("<script>", "");
;   }
;
; HTML tag names are case-insensitive, so the browser runs a script if the
; lower-cased output contains "<script>".  Can that happen?
(set-logic QF_SLIA)
(declare-const comment String)
(define-fun out () String (str.replace_all comment "<script>" ""))
(assert (str.contains (str.to_lower out) "<script>"))
(check-sat)
(get-model)

xss-strip-nested.query:
; The developer adds case folding: lower-case first, then delete the tags.
;
;   function sanitize(comment) {
;     return comment.toLowerCase().replaceAll("<script>", "");
;   }
;
; Still exploitable?
(set-logic QF_SLIA)
(declare-const comment String)
(define-fun out () String (str.replace_all (str.to_lower comment) "<script>" ""))
(assert (str.contains out "<script>"))
(check-sat)
(get-model)
